import{_ as e,c as r,o as s,ae as i}from"./chunks/framework.CHDT0Kbg.js";const u=JSON.parse('{"title":"Instalar Persim","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/installation.md","filePath":"es/guide/installation.md","lastUpdated":1795170900000}'),t={name:"es/guide/installation.md"};function o(l,a,n,c,d,p){return s(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="instalar-persim" tabindex="-1">Instalar Persim <a class="header-anchor" href="#instalar-persim" aria-label="Permalink to &quot;Instalar Persim&quot;">​</a></h1><p>Descárgalo, ponlo como predeterminado y trae tus marcadores.</p><h2 id="descarga-e-instalacion" tabindex="-1">Descarga e instalación <a class="header-anchor" href="#descarga-e-instalacion" aria-label="Permalink to &quot;Descarga e instalación&quot;">​</a></h2><ol><li>Abre la <a href="https://apps.apple.com/app/id6835099132" target="_blank" rel="noreferrer">Mac App Store</a> y busca Persim.</li><li>Tras descargarlo, arrastra la app a la carpeta Aplicaciones.</li><li>Para hacerlo predeterminado: <strong>Ajustes del sistema → Navegador web predeterminado</strong> → Persim.</li></ol><p>Necesita macOS 12 o posterior, en Apple Silicon e Intel.</p><h2 id="tu-primer-minuto" tabindex="-1">Tu primer minuto <a class="header-anchor" href="#tu-primer-minuto" aria-label="Permalink to &quot;Tu primer minuto&quot;">​</a></h2><ul><li>En <code>persim://settings</code> → <strong>General</strong>, elige aspecto, color y barra de marcadores.</li><li>Hay 25 idiomas; el cambio se aplica al volver a abrir la ventana.</li><li>La nueva pestaña ya incluye sitios populares y accesos a IA.</li></ul><h2 id="traer-tus-marcadores" tabindex="-1">Traer tus marcadores <a class="header-anchor" href="#traer-tus-marcadores" aria-label="Permalink to &quot;Traer tus marcadores&quot;">​</a></h2><ol><li>Exporta los marcadores a HTML desde Chrome o Edge.</li><li>En el gestor de marcadores de Persim, elige <strong>Importar HTML</strong>.</li><li>Las carpetas anidadas se restauran y las URL duplicadas se omiten.</li></ol><h2 id="actualizaciones" tabindex="-1">Actualizaciones <a class="header-anchor" href="#actualizaciones" aria-label="Permalink to &quot;Actualizaciones&quot;">​</a></h2><p>Consigue las nuevas versiones en la pestaña «Actualizaciones» de Mac App Store. Tus datos se conservan.</p>',11)])])}const h=e(t,[["render",o]]);export{u as __pageData,h as default};
